parameters.jsCode:
// Config lives here as a node, NOT in n8n Variables ($vars): Variables are a
// licensed feature, and on community n8n they resolve to undefined silently,
// which would send the introduction with an empty CC and still look like a
// success. Edit these three values after import.
return $input.all().map(i => ({ json: { ...i.json,
  SHERIF_EMAIL:      'sherif.hani@energygreenprint.net.au',
  EMAAS_CAMPAIGN_ID: 'PASTE_CAMPAIGN_ID_HERE',
  SLACK_WEBHOOK_URL: 'PASTE_SLACK_WEBHOOK_HERE',
  DEBUG_RAW:         true      // first run: post the raw payload to Slack so
                               // the real field names can be pinned down
}}));

// Field names are NOT guesses. They are the contract the repo's production
// webhook handler already runs on (instantly-autoreply/scripts/
// instantly_autoreply.py): the Instantly payload is FLAT and carries
// campaign_id, campaign_name, email_account, email_id, lead_email,
// reply_subject, reply_text, reply_html. It does NOT carry the lead's first
// name or company, which is why the next node looks the lead up.
const cfg = $input.first().json;
const b = cfg.body ?? cfg;

return [{ json: {
  SHERIF_EMAIL:      cfg.SHERIF_EMAIL,
  EMAAS_CAMPAIGN_ID: cfg.EMAAS_CAMPAIGN_ID,
  SLACK_WEBHOOK_URL: cfg.SLACK_WEBHOOK_URL,
  campaignId: b.campaign_id  || '',
  email:      b.lead_email   || '',
  eaccount:   b.email_account || '',
  replyUuid:  b.email_id     || '',
  subject:    b.reply_subject || '',
  replyText:  b.reply_text   || ''
}}];

// Fire-once guard. Instantly retries a failed delivery three times and a lead
// can be re-marked interested by hand, so without this a prospect can receive
// the same introduction twice at exactly the wrong moment.
const staticData = $getWorkflowStaticData('global');
staticData.introduced = staticData.introduced || {};

const ctx = $('Normalise payload').item.json;
const key = (ctx.email || '').toLowerCase();
if (!key || staticData.introduced[key]) { return []; }
staticData.introduced[key] = new Date().toISOString();

// /leads/list returns { items: [...] }; verified live against the API.
const lead = ($json.items && $json.items[0]) || {};
const pl   = lead.payload || {};
const first   = lead.first_name || pl.firstName || 'there';
const company = lead.company_name || pl.companyName || 'their site';
const title   = lead.job_title || pl.dm_title || '';
const city    = pl.site_city || '';
const state   = pl.site_state || '';
const site    = city ? ` (${city}${state ? ', ' + state : ''})` : '';

// Connector framework: Jude introduces, Sherif's credentials are attributed
// to Sherif, no sign-off because the sending account signature carries it.
const lines = [
  `Hi ${first},`,
  ``,
  `Great. Putting you in touch with Sherif now, copied here.`,
  ``,
  `Sherif Hani runs Energy GreenPrint in Melbourne. He is a chartered electrical engineer with 20 years on industrial sites, and the energy audit is his. He will pick this up from here.`,
  ``,
  `Sherif, ${first} is at ${company}${site}. Over to you.`
];

return [{ json: { ...ctx, first, company, title,
  introHtml: '<div>' + lines.join('<br />') + '</div>' } }];

parameters.jsonBody:
={{ JSON.stringify({
  eaccount: $json.eaccount,
  reply_to_uuid: $json.replyUuid,
  subject: $json.subject,
  cc_address_email_list: $json.SHERIF_EMAIL,
  body: { html: $json.introHtml }
}) }}

={{ JSON.stringify({ text: `:handshake: *Intro made* — ${$('Build intro (fire once)').item.json.company}
${$('Build intro (fire once)').item.json.first} (${$('Build intro (fire once)').item.json.title || 'no title'}) <${$('Build intro (fire once)').item.json.email}>
Sherif CC'd on the thread.

_Their reply:_ ${($('Build intro (fire once)').item.json.replyText || '').slice(0, 300)}` }) }}
